/* ===== x13_production.js ===== */
/* ============================================================================
   v5.5 LAYER 13 — Production, corporate & rental options; assistants and
   longer-term differentiators. Inventory & rental allocation, equipment /
   vehicle dispatch, floor plans, creative boards, venue/banquet operations
   (BEO), delegates & registration (public form), ticketing / exhibitors /
   sponsors with refunds, speakers & sessions with conflicts and stage cues,
   travel & insurance records; assistants (receipt extraction review, draft
   quote, timeline draft, change summary, risk explanations), private
   estimating intelligence, cross-company benchmark opt-in, sourcing network
   (deferred state), multi-currency accounting.
   ========================================================================== */
coll('vehicles','inventory','allocations','trips','floorPlans','boards','delegates','ticketTypes','sponsors','exhibitors','ticketSales','confSessions','speakers','travelBookings','fxRates');
/* ---------- Production tab ---------- */
addTab('production','Production',tabProduction,(e,pre)=>!pre&&(modOn('inventory')||modOn('dispatch')||modOn('floorplans')||modOn('creative')||modOn('venueops'))&&(can('vendors')||me().role==='staff'),'Work');
function tabProduction(e,c){return [modOn('inventory')?inventoryCard(e):'',modOn('dispatch')?dispatchCard(e):'',modOn('floorplans')?floorPlanCard(e):'',modOn('creative')?boardsCard(e):'',modOn('venueops')?beoCard(e):''].join('')||'<div class="card muted">All production modules are switched off.</div>'}
/* inventory */
function invAvail(item,from,to,exceptId){const used=S.allocations.filter(a=>a.itemId===item.id&&a.id!==exceptId&&!a.returnedAt).filter(a=>{const e=ev(a.eventId);if(!e)return false;const f=a.from||e.startDate,t=a.to||e.endDate||e.startDate;return !(t<from||f>to)});return item.qty-sum(used,a=>a.qty)}
function inventoryCard(e){const al=S.allocations.filter(a=>a.eventId===e.id);const lk=locked(e);return `<div class="card" style="margin-bottom:12px"><div class="row between"><div><h3>Inventory & rentals</h3><div class="small muted">Your own reusable stock (not supplier availability). Allocation per event with dates; clashes flagged; load-out / load-in ticks; damage or loss becomes an expense against the event.</div></div>${can('vendors')&&!lk?`<div class="row" style="gap:6px"><a class="btn sm" href="#inventory" style="text-decoration:none">Stock list</a><button class="btn sm pri" data-act="alloc-add">+ Allocate</button></div>`:''}</div><div class="list" style="margin-top:6px">${al.map(a=>{const it=S.inventory.find(i=>i.id===a.itemId)||{name:'?',qty:0};const avail=invAvail(it,a.from||e.startDate,a.to||e.endDate||e.startDate,a.id);return `<div class="item" style="padding:6px 0"><div class="row between"><div class="small"><b>${esc(it.name)}</b> × ${a.qty} · ${fmtShort(a.from||e.startDate)}–${fmtShort(a.to||e.endDate||e.startDate)} ${avail<0?`<span class="pill bad">over-allocated by ${-avail}</span>`:''} <span class="steps" style="display:inline-flex"><span class="st ${a.outAt?'done':''}">loaded out</span><span class="st ${a.returnedAt?'done':''}">returned</span>${a.damage?'<span class="st bad">damage: '+esc(a.damage)+'</span>':''}</span><div class="meta">${a.outAt?'out '+fmtTs(a.outAt)+' by '+esc(user(a.outBy).name):''}${a.returnedAt?' · back '+fmtTs(a.returnedAt)+(a.returnedQty<a.qty?' · '+(a.qty-a.returnedQty)+' missing':''):''}</div></div>${!lk?`<div class="row" style="gap:4px">${!a.outAt?`<button class="btn sm" data-act="alloc-out" data-id="${a.id}">Load out</button>`:!a.returnedAt?`<button class="btn sm pri" data-act="alloc-return" data-id="${a.id}">Return</button>`:''}<button class="btn sm" data-act="alloc-del" data-id="${a.id}">×</button></div>`:''}</div></div>`}).join('')||'<div class="muted small">Nothing allocated from stock.</div>'}</div></div>`}
addPage('inventory','Inventory',vInventory,()=>modOn('inventory')&&can('vendors'));
function vInventory(){const items=S.inventory;return `${topbar()}<div class="row between"><h1>Inventory</h1>${can('directory.edit')?`<button class="btn sm pri" data-act="item-add">+ Item</button>`:''}</div><div class="small muted" style="margin:4px 0 10px">Owned stock: quantity, condition, value, maintenance due. Availability on a date = quantity − allocations overlapping that date.</div><div class="card"><div class="scroll"><table><thead><tr><th>Item</th><th class="r">Qty</th><th class="r">Free today</th><th>Condition</th><th class="r">Value</th><th>Maintenance</th><th></th></tr></thead><tbody>${items.map(i=>`<tr><td><b>${esc(i.name)}</b>${i.sku?` <span class="mono small">${esc(i.sku)}</span>`:''}<div class="meta">${esc(i.notes||'')}</div></td><td class="r num">${i.qty}</td><td class="r num">${invAvail(i,todayStr(),todayStr())}</td><td>${esc(i.condition||'')}</td><td class="r num">${inr(i.valuePaise||0)}</td><td class="${i.maintenanceDue&&i.maintenanceDue<todayStr()?'':'small muted'}">${i.maintenanceDue?fmtShort(i.maintenanceDue)+(i.maintenanceDue<todayStr()?' <span class="pill bad">overdue</span>':''):'—'}</td><td>${can('directory.edit')?`<button class="btn sm" data-act="item-edit" data-id="${i.id}">Edit</button>`:''}</td></tr>`).join('')||'<tr><td colspan="7" class="muted">No stock recorded.</td></tr>'}</tbody></table></div></div>`}
act('item-add',()=>mItem(null));act('item-edit',({id})=>mItem(S.inventory.find(i=>i.id===id)));
function mItem(i){const isNew=!i;i=i||{name:'',sku:'',qty:1,condition:'good',valuePaise:0,maintenanceDue:null,notes:''};openModal(`${hd(isNew?'Add item':'Edit item')}<form id="f-it2"><label for="itn">Name</label><input id="itn" required value="${esc(i.name)}"><div class="grid g3" style="gap:8px"><div><label for="its">SKU / tag</label><input id="its" value="${esc(i.sku||'')}"></div><div><label for="itq">Quantity</label><input id="itq" inputmode="numeric" value="${i.qty}"></div><div><label for="itc">Condition</label><select id="itc">${['good','fair','needs repair','retired'].map(c=>`<option ${i.condition===c?'selected':''}>${c}</option>`).join('')}</select></div></div><div class="two"><div><label for="itv">Value (₹)</label><input id="itv" inputmode="decimal" value="${(i.valuePaise||0)/100}"></div><div><label for="itm">Maintenance due</label><input id="itm" type="date" value="${i.maintenanceDue||''}"></div></div><label for="itno">Notes</label><input id="itno" value="${esc(i.notes||'')}">${ft('Save')}</form>`);F('f-it2').addEventListener('submit',x=>{x.preventDefault();const d={name:F('itn').value.trim(),sku:F('its').value.trim(),qty:parseInt(F('itq').value)||0,condition:F('itc').value,valuePaise:toPaise(F('itv').value)||0,maintenanceDue:F('itm').value||null,notes:F('itno').value.trim()};if(isNew)S.inventory.push(stamp(Object.assign({id:uid()},d)));else{Object.assign(i,d);touch(i)}save();closeModal();render()})}
act('alloc-add',({E})=>{const e=E();openModal(`${hd('Allocate from stock')}<form id="f-al"><label for="ali">Item</label><select id="ali">${S.inventory.filter(i=>i.condition!=='retired').map(i=>`<option value="${i.id}">${esc(i.name)} (free ${invAvail(i,e.startDate,e.endDate||e.startDate)} of ${i.qty})</option>`).join('')}</select><div class="grid g3" style="gap:8px"><div><label for="alq">Qty</label><input id="alq" inputmode="numeric" value="1"></div><div><label for="alf">From</label><input id="alf" type="date" value="${addDays(e.startDate,-1)}"></div><div><label for="alt">To</label><input id="alt" type="date" value="${addDays(e.endDate||e.startDate,1)}"></div></div>${ft('Allocate')}</form>`);F('f-al').addEventListener('submit',x=>{x.preventDefault();const it=S.inventory.find(i=>i.id===F('ali').value);const q=parseInt(F('alq').value)||1;const avail=invAvail(it,F('alf').value,F('alt').value);if(q>avail&&!confirm(`Only ${avail} free in that window. Allocate anyway (another event will be short)?`))return;S.allocations.push({id:uid(),eventId:e.id,itemId:it.id,qty:q,from:F('alf').value,to:F('alt').value,outAt:null,returnedAt:null,damage:''});audit('create','allocations',it.id,q+' to '+e.name,e.id);save();closeModal();render()})});
act('alloc-out',({id})=>{const a=S.allocations.find(x=>x.id===id);a.outAt=nowISO();a.outBy=UI.userId;save();render()});
act('alloc-return',({id})=>{const a=S.allocations.find(x=>x.id===id);const it=S.inventory.find(i=>i.id===a.itemId);openModal(`${hd('Return: '+esc(it.name))}<form id="f-rt"><label for="rtq">Quantity back</label><input id="rtq" class="big" inputmode="numeric" value="${a.qty}"><label for="rtd">Damage / loss</label><input id="rtd" placeholder="2 chairs broken"><label for="rtc">Cost to the event (₹, becomes an expense)</label><input id="rtc" inputmode="decimal" value="0">${ft('Record return')}</form>`);F('f-rt').addEventListener('submit',x=>{x.preventDefault();a.returnedAt=nowISO();a.returnedBy=UI.userId;a.returnedQty=parseInt(F('rtq').value)||0;a.damage=F('rtd').value.trim();const cost=toPaise(F('rtc').value)||0;if(cost){S.expenses.push(stamp({id:uid(),eventId:a.eventId,functionName:'',amountPaise:cost,category:'Other',source:'company',date:todayStr(),note:'Stock damage/loss: '+it.name+' — '+a.damage,photo:'',spentBy:UI.userId,settlementId:null,status:'approved',allocationId:a.id}))}if(a.returnedQty<a.qty){it.qty-=(a.qty-a.returnedQty);it.notes=(it.notes||'')+` ${a.qty-a.returnedQty} lost on ${(ev(a.eventId)||{}).name}.`}if(a.damage&&!/lost/.test(a.damage))it.condition='needs repair';save();closeModal();render()})});
act('alloc-del',({id})=>{S.allocations=S.allocations.filter(a=>a.id!==id);save();render()});
/* dispatch */
function dispatchCard(e){const trips=S.trips.filter(t=>t.eventId===e.id).sort((a,b)=>(a.date+a.window).localeCompare(b.date+b.window));const lk=locked(e);return `<div class="card" style="margin-bottom:12px"><div class="row between"><div><h3>Equipment & vehicle dispatch</h3><div class="small muted">Trips with vehicle, window, packing list (from allocations), driver, handover acknowledgement and return deadline.</div></div>${can('vendors')&&!lk?`<div class="row" style="gap:6px"><button class="btn sm" data-act="vehicle-add">+ Vehicle</button><button class="btn sm pri" data-act="trip-add">+ Trip</button></div>`:''}</div><div class="list" style="margin-top:6px">${trips.map(t=>{const v=S.vehicles.find(x=>x.id===t.vehicleId)||{name:'?'};const load=t.allocIds.map(id=>S.allocations.find(a=>a.id===id)).filter(Boolean);return `<div class="item" style="padding:6px 0"><div class="row between"><div class="small"><b>${esc(v.name)}</b> · ${fmtShort(t.date)} ${esc(t.window)} · ${esc(t.from)} → ${esc(t.to)}${t.driverId?' · driver '+esc(crewOf(t.driverId).name):''}<div class="meta">Load: ${load.map(a=>esc((S.inventory.find(i=>i.id===a.itemId)||{}).name||'')+' ×'+a.qty).join(', ')||'—'}${t.pax?' · '+t.pax+' pax':''} ${t.handoverAt?`· handed over ${fmtTs(t.handoverAt)} to ${esc(t.handoverTo)}`:''} ${t.returnBy?'· return by '+fmtShort(t.returnBy)+(t.returnBy<todayStr()&&!t.returnedAt?' <span class="pill bad">overdue</span>':''):''}</div></div>${!lk?`<div class="row" style="gap:4px"><button class="btn sm" data-act="trip-pack" data-id="${t.id}">Packing list</button>${!t.handoverAt?`<button class="btn sm" data-act="trip-handover" data-id="${t.id}">Handover</button>`:''}<button class="btn sm" data-act="trip-del" data-id="${t.id}">×</button></div>`:''}</div></div>`}).join('')||'<div class="muted small">No trips.</div>'}</div></div>`}
act('vehicle-add',()=>{openModal(`${hd('Vehicle')}<form id="f-vh"><label for="vhn">Name / registration</label><input id="vhn" required><div class="two"><div><label for="vhc">Capacity (pax or load units)</label><input id="vhc" inputmode="numeric" value="6"></div><div><label for="vhd">Default driver (crew)</label><select id="vhd"><option value="">—</option>${S.crew.map(k=>`<option value="${k.id}">${esc(k.name)}</option>`).join('')}</select></div></div>${ft('Add')}</form>`);F('f-vh').addEventListener('submit',x=>{x.preventDefault();S.vehicles.push({id:uid(),name:F('vhn').value.trim(),capacity:parseInt(F('vhc').value)||1,driverCrewId:F('vhd').value||null});save();closeModal();render()})});
act('trip-add',({E})=>{const e=E();openModal(`${hd('Trip')}<form id="f-tr"><label for="trv">Vehicle</label><select id="trv">${S.vehicles.map(v=>`<option value="${v.id}">${esc(v.name)} (${v.capacity})</option>`).join('')}</select><div class="grid g3" style="gap:8px"><div><label for="trd">Date</label><input id="trd" type="date" value="${addDays(e.startDate,-1)}"></div><div><label for="trw">Window</label><input id="trw" value="14:00–17:00"></div><div><label for="trdr">Driver</label><select id="trdr"><option value="">—</option>${S.crew.map(k=>`<option value="${k.id}">${esc(k.name)}</option>`).join('')}</select></div></div><div class="two"><div><label for="trf">From</label><input id="trf" value="Warehouse"></div><div><label for="trt">To</label><input id="trt" value="${esc(e.venue||'')}"></div></div><label>Load (allocated stock)</label><div class="chips">${S.allocations.filter(a=>a.eventId===e.id).map(a=>`<label class="btn chip sm" style="margin:0"><input type="checkbox" class="trl" value="${a.id}" style="margin-right:4px">${esc((S.inventory.find(i=>i.id===a.itemId)||{}).name||'')} ×${a.qty}</label>`).join('')||'<span class="small muted">no allocations</span>'}</div><div class="two"><div><label for="trp">Passengers</label><input id="trp" inputmode="numeric" value="0"></div><div><label for="trr">Return by</label><input id="trr" type="date" value="${addDays(e.endDate||e.startDate,1)}"></div></div>${ft('Save')}</form>`);F('f-tr').addEventListener('submit',x=>{x.preventDefault();const v=S.vehicles.find(z=>z.id===F('trv').value);const pax=parseInt(F('trp').value)||0;if(v&&pax>v.capacity)return toast(`${v.name} carries ${v.capacity}`);S.trips.push({id:uid(),eventId:e.id,vehicleId:F('trv').value,date:F('trd').value,window:F('trw').value.trim(),driverId:F('trdr').value||null,from:F('trf').value.trim(),to:F('trt').value.trim(),allocIds:[...document.querySelectorAll('.trl:checked')].map(c=>c.value),pax,returnBy:F('trr').value||null,handoverAt:null});save();closeModal();render()})});
act('trip-pack',({id})=>{const t=S.trips.find(x=>x.id===id);const e=ev(t.eventId);const v=S.vehicles.find(x=>x.id===t.vehicleId)||{name:'?'};const lines=t.allocIds.map(i=>S.allocations.find(a=>a.id===i)).filter(Boolean).map(a=>({t:`[ ] ${(S.inventory.find(i=>i.id===a.itemId)||{}).name} × ${a.qty}`}));downloadBlob('packing-list.pdf',makePdf(`Packing list — ${e.name} — ${v.name} — ${fmtDate(t.date)} ${t.window}`,[{t:`${t.from} → ${t.to} · driver ${t.driverId?crewOf(t.driverId).name:'—'}`},{t:''}].concat(lines,[{t:''},{t:'Handed over by: ____________   Received by: ____________   Time: ______'}])))});
act('trip-handover',({id})=>{const t=S.trips.find(x=>x.id===id);openModal(`${hd('Handover')}<form id="f-ho"><label for="hon">Received by (name at the venue)</label><input id="hon" required>${ft('Record')}</form>`);F('f-ho').addEventListener('submit',x=>{x.preventDefault();t.handoverAt=nowISO();t.handoverTo=F('hon').value.trim();t.handoverBy=UI.userId;t.allocIds.forEach(i=>{const a=S.allocations.find(z=>z.id===i);if(a&&!a.outAt){a.outAt=nowISO();a.outBy=UI.userId}});save();closeModal();render()})});
act('trip-del',({id})=>{S.trips=S.trips.filter(t=>t.id!==id);save();render()});
/* floor plans */
function floorPlanCard(e){const plans=S.floorPlans.filter(p=>p.eventId===e.id);return `<div class="card" style="margin-bottom:12px"><div class="row between"><div><h3>Floor plans</h3><div class="small muted">Zones on a simple canvas with scale, versioned; client/venue approval through the same approval links. For real drawings link the design file — this is not a CAD tool.</div></div>${can('events.edit')&&!locked(e)?`<button class="btn sm pri" data-act="plan-add">+ Plan</button>`:''}</div><div class="list" style="margin-top:6px">${plans.map(p=>`<div class="item" style="padding:6px 0"><div class="row between"><div class="small"><b>${esc(p.fn)} · v${p.version}</b> · ${p.widthM}×${p.heightM} m · ${p.zones.length} zones${p.fileUrl?' · <a href="'+esc(p.fileUrl)+'" target="_blank" rel="noopener">design file</a>':''} <span class="pill ${p.status==='approved'?'ok':p.status==='superseded'?'grey':'warn'}">${p.status}</span>${p.approvedBy?' · '+esc(p.approvedBy):''}</div><div class="row" style="gap:4px">${p.status!=='superseded'&&can('events.edit')&&!locked(e)?`<button class="btn sm" data-act="plan-edit" data-id="${p.id}">Edit zones</button><button class="btn sm" data-act="plan-approve" data-id="${p.id}">Send for approval</button>`:''}</div></div><div class="plan" style="margin-top:6px;height:180px">${p.zones.map(z=>`<div class="zone" style="left:${z.x}%;top:${z.y}%;width:${z.w}%;height:${z.h}%">${esc(z.name)}</div>`).join('')}</div></div>`).join('')||'<div class="muted small">No plans.</div>'}</div></div>`}
act('plan-add',({E})=>{const e=E();openModal(`${hd('Floor plan')}<form id="f-fp"><label for="fpf">Function</label><select id="fpf">${fnNames(e).map(f=>`<option>${esc(f)}</option>`).join('')}</select><div class="two"><div><label for="fpw">Width (m)</label><input id="fpw" inputmode="decimal" value="30"></div><div><label for="fph">Depth (m)</label><input id="fph" inputmode="decimal" value="20"></div></div><label for="fpu">Design file link (optional)</label><input id="fpu" placeholder="https://…"><label for="fpz">Zones (name, x%, y%, w%, h% — one per line)</label><textarea id="fpz" placeholder="Stage,40,2,20,12&#10;Mandap,42,16,16,14&#10;Dining,5,60,90,35"></textarea>${ft('Create')}</form>`);F('f-fp').addEventListener('submit',x=>{x.preventDefault();const fn=F('fpf').value;S.floorPlans.filter(p=>p.eventId===e.id&&p.fn===fn&&p.status!=='superseded').forEach(p=>p.status='superseded');const zones=F('fpz').value.split('\n').map(l=>l.split(',').map(s=>s.trim())).filter(a=>a.length>=5).map(a=>({name:a[0],x:+a[1],y:+a[2],w:+a[3],h:+a[4]}));S.floorPlans.push(stamp({id:uid(),eventId:e.id,fn,version:S.floorPlans.filter(p=>p.eventId===e.id&&p.fn===fn).length+1,widthM:parseFloat(F('fpw').value)||0,heightM:parseFloat(F('fph').value)||0,fileUrl:F('fpu').value.trim(),zones,status:'draft'}));save();closeModal();render()})});
act('plan-edit',({id})=>{const p=S.floorPlans.find(x=>x.id===id);openModal(`${hd('Zones v'+p.version)}<form id="f-fz"><textarea id="fzz" style="min-height:120px">${esc(p.zones.map(z=>[z.name,z.x,z.y,z.w,z.h].join(',')).join('\n'))}</textarea><div class="help">Editing an approved plan creates a new version and asks for approval again.</div>${ft('Save')}</form>`);F('f-fz').addEventListener('submit',x=>{x.preventDefault();const zones=F('fzz').value.split('\n').map(l=>l.split(',').map(s=>s.trim())).filter(a=>a.length>=5).map(a=>({name:a[0],x:+a[1],y:+a[2],w:+a[3],h:+a[4]}));if(p.status==='approved'){p.status='superseded';S.floorPlans.push(stamp(Object.assign({},p,{id:uid(),version:p.version+1,zones,status:'draft',approvedBy:null})))}else{p.zones=zones;touch(p)}save();closeModal();render()})});
act('plan-approve',({E,id})=>{const e=E();const p=S.floorPlans.find(x=>x.id===id);const r=stamp({id:uid(),eventId:e.id,kind:'Floor plan',desc:`${p.fn} layout v${p.version}`,planId:p.id,sentAt:nowISO(),status:'sent',decidedAt:null,decidedBy:'',note:'',decisionMaker:e.client,expiresAt:addDays(todayStr(),14),revision:'fp'+p.id+'v'+p.version,thread:[]});clientLink(r);S.clientReqs.push(r);p.status='sent';save();render();mCopy('Floor plan approval',waReq(r))});
/* creative boards */
function boardsCard(e){const bs=S.boards.filter(b=>b.eventId===e.id);return `<div class="card" style="margin-bottom:12px"><div class="row between"><div><h3>Creative boards</h3><div class="small muted">Moodboards and proofs from the event's documents, each item with a version-specific approval, linked to the scope line it affects so the décor budget and the approved look stay in step.</div></div>${can('events.edit')&&!locked(e)?`<button class="btn sm pri" data-act="board-add">+ Board</button>`:''}</div><div class="list" style="margin-top:6px">${bs.map(b=>`<div class="item" style="padding:6px 0"><div class="row between"><div class="small"><b>${esc(b.title)}</b>${b.scopeLineId?' · '+esc((S.scopeLines.find(l=>l.id===b.scopeLineId)||{}).desc||''):''} · ${b.items.length} item(s) · ${b.items.filter(i=>i.status==='approved').length} approved</div><div class="row" style="gap:4px">${can('events.edit')&&!locked(e)?`<button class="btn sm" data-act="board-item" data-id="${b.id}">+ Item</button>`:''}</div></div><div class="row" style="gap:8px;margin-top:6px;flex-wrap:wrap">${b.items.map((it,i)=>{const d=S.docs.find(x=>x.id===it.docId);return `<div style="width:150px"><div style="height:90px;border-radius:8px;border:1px solid var(--line);overflow:hidden;background:var(--bg);display:flex;align-items:center;justify-content:center">${d&&docData(d)&&d.type.startsWith('image/')?`<img src="${docData(d)}" style="width:100%;height:100%;object-fit:cover" data-act="view-doc" data-id="${d.id}">`:esc((d||{}).name||'?')}</div><div class="small">${esc(it.note||'')} <span class="pill ${it.status==='approved'?'ok':it.status==='rejected'?'bad':'warn'}">${it.status} v${it.version}</span></div>${can('events.edit')&&!locked(e)&&it.status==='proposed'?`<button class="btn sm" data-act="board-send" data-id="${b.id}" data-v="${i}">Send for approval</button>`:''}</div>`}).join('')||'<span class="muted small">Empty board.</span>'}</div></div>`).join('')||'<div class="muted small">No boards.</div>'}</div></div>`}
act('board-add',({E})=>{const e=E();openModal(`${hd('New board')}<form id="f-bd"><label for="bdt">Title</label><input id="bdt" required placeholder="Mandap concept"><label for="bds">Linked scope line</label><select id="bds"><option value="">—</option>${scopeOf(e.id).map(l=>`<option value="${l.id}">${esc(l.category)} · ${esc(l.desc)}</option>`).join('')}</select>${ft('Create')}</form>`);F('f-bd').addEventListener('submit',x=>{x.preventDefault();S.boards.push(stamp({id:uid(),eventId:e.id,title:F('bdt').value.trim(),scopeLineId:F('bds').value||null,items:[]}));save();closeModal();render()})});
act('board-item',({E,id})=>{const e=E();const b=S.boards.find(x=>x.id===id);openModal(`${hd('Add to board')}<form id="f-bi"><label for="bid">Document (image)</label><select id="bid">${live(S.docs).filter(d=>d.eventId===e.id&&d.type.startsWith('image/')).map(d=>`<option value="${d.id}">${esc(d.name)}</option>`).join('')}</select><label for="bin">Note</label><input id="bin" placeholder="Gold + white, option B">${ft('Add')}</form>`);F('f-bi').addEventListener('submit',x=>{x.preventDefault();if(!F('bid').value)return toast('Upload an image to Documents first');b.items.push({docId:F('bid').value,note:F('bin').value.trim(),status:'proposed',version:1});touch(b);save();closeModal();render()})});
act('board-send',({E,id,v})=>{const e=E();const b=S.boards.find(x=>x.id===id);const it=b.items[+v];const r=stamp({id:uid(),eventId:e.id,kind:'Design',desc:`${b.title}: ${it.note||'item '+(+v+1)}`,docIds:[it.docId],boardId:b.id,boardItem:+v,sentAt:nowISO(),status:'sent',decidedAt:null,decidedBy:'',note:'',decisionMaker:e.client,expiresAt:addDays(todayStr(),14),revision:'bd'+b.id+':'+v+':'+it.version,thread:[]});clientLink(r);S.clientReqs.push(r);save();render();mCopy('Design approval',waReq(r))});
const _clDecideHook=clDecide;clDecide=function(status){const r=S.clientReqs.find(x=>x.token===S.ui.clientToken);_clDecideHook(status);if(r&&r.boardId&&(status==='approved'||status==='declined')){const b=S.boards.find(x=>x.id===r.boardId);if(b&&b.items[r.boardItem]){b.items[r.boardItem].status=status==='approved'?'approved':'rejected';save()}}if(r&&r.planId&&(status==='approved'||status==='declined')){const p=S.floorPlans.find(x=>x.id===r.planId);if(p){p.status=status==='approved'?'approved':'draft';p.approvedBy=status==='approved'?r.decidedBy:null;save()}}};
/* venue / banquet operations: BEO */
function beoText(e){const cc=e.cateringCount||{};return `BANQUET EVENT ORDER\n${e.name} · ${e.client}\n${S.company.name}\n\n`+fnNames(e).map(fn=>{const d=fnOf(e,fn);const rc=modOn('guests')?rsvpCounts(e)[fn]:null;const cms=agreedComms(e.id).filter(cm=>!(cm.functions||[]).length||cm.functions.includes(fn));return `${fn.toUpperCase()} — ${fmtDate(d.date)}${d.start?' from '+d.start:''}\nRoom/area: ${d.venue||e.venue||'TBD'}\nGuaranteed count: ${cc[fn]?cc[fn].count+' (approved '+fmtShort(cc[fn].at.slice(0,10))+')':'NOT YET APPROVED'}${rc?' · RSVP yes '+rc.yes+(Object.keys(rc.dietary).length?' · dietary: '+Object.entries(rc.dietary).map(([k,v])=>k+' '+v).join(', '):''):''}\nSetup: ${cms.map(cm=>vendor(cm.vendorId).name+(cm.setupWindow?' ('+cm.setupWindow+')':'')).join('; ')||'—'}\nRun: ${live(S.runsheet).filter(r=>r.eventId===e.id&&r.functionName===fn).sort((a,b)=>a.time.localeCompare(b.time)).map(r=>r.time+' '+r.title).join('; ')||'—'}\n`}).join('\n')+`\nMinimum spend / room blocks: ${(e.venueOps||{}).minSpend?inr(e.venueOps.minSpend)+' minimum':'not applicable'}${(e.venueOps||{}).rooms?' · rooms blocked: '+e.venueOps.rooms:''}\nKitchen handoff: ${(e.venueOps||{}).kitchen||'—'}`}
function beoCard(e){const vo=e.venueOps||{};return `<div class="card"><div class="row between"><div><h3>Venue / banquet operations</h3><div class="small muted">For venue and catering buyers: a Banquet Event Order built from functions, guaranteed counts, vendor setup windows and the run sheet; room blocks and minimum spend recorded against the venue agreement.</div></div><div class="row" style="gap:6px">${can('events.edit')&&!locked(e)?`<button class="btn sm" data-act="venueops-edit">Venue terms</button>`:''}<button class="btn sm" data-act="beo-copy">BEO text</button><button class="btn sm" data-act="beo-pdf">BEO PDF</button></div></div>${vo.minSpend||vo.rooms||vo.kitchen?`<div class="kv small" style="margin-top:6px"><b>Minimum spend</b><span>${vo.minSpend?inr(vo.minSpend):'—'}</span><b>Room blocks</b><span>${esc(vo.rooms||'—')}</span><b>Kitchen handoff</b><span>${esc(vo.kitchen||'—')}</span></div>`:''}</div>`}
act('venueops-edit',({E})=>{const e=E();const vo=e.venueOps||{};openModal(`${hd('Venue terms')}<form id="f-vo"><label for="vom">Minimum spend (₹, ex-tax)</label><input id="vom" inputmode="decimal" value="${vo.minSpend?vo.minSpend/100:''}"><label for="vor">Room blocks (rooms × nights, release date)</label><input id="vor" value="${esc(vo.rooms||'')}"><label for="vok">Kitchen / service handoff notes</label><textarea id="vok">${esc(vo.kitchen||'')}</textarea>${ft('Save')}</form>`);F('f-vo').addEventListener('submit',x=>{x.preventDefault();e.venueOps={minSpend:toPaise(F('vom').value),rooms:F('vor').value.trim(),kitchen:F('vok').value.trim()};touch(e);save();closeModal();render()})});
act('beo-copy',({E})=>mCopy('Banquet event order',beoText(E())));act('beo-pdf',({E})=>{const e=E();downloadBlob('BEO-'+e.name.replace(/\W+/g,'_')+'.pdf',makePdf('Banquet event order',beoText(e).split('\n')))});
/* ---------- Registration tab (corporate) ---------- */
addTab('registration','Registration',tabRegistration,(e,pre)=>!pre&&(modOn('registration')||modOn('ticketing')||modOn('speakers'))&&e.type==='corporate'&&(can('events.edit')||can('tasks.manage')),'Work');
function tabRegistration(e,c){return [modOn('registration')?delegatesCard(e):'',modOn('ticketing')?ticketingCard(e):'',modOn('speakers')?sessionsCard(e):''].join('')}
function delegatesCard(e){const ds=S.delegates.filter(d=>d.eventId===e.id);const tt=S.ticketTypes.filter(t=>t.eventId===e.id);const q=(S.ui.dq2||'').toLowerCase();const shown=ds.filter(d=>!q||(d.name+' '+d.email+' '+(d.company||'')).toLowerCase().includes(q));return `<div class="card" style="margin-bottom:12px"><div class="row between"><div><h3>Delegates <span class="small muted">${ds.length} · ${ds.filter(d=>d.status==='checked-in').length} checked in</span></h3><div class="small muted">Public registration form, ticket class, company, consent for attendee messaging. Registration is not a confirmed booking for the client: it is attendance.</div></div><div class="row" style="gap:6px"><a class="btn sm" href="#register/${registerToken(e)}" style="text-decoration:none">Open registration form</a>${can('events.edit')&&!locked(e)?`<button class="btn sm pri" data-act="delegate-add">+ Delegate</button>`:''}</div></div><input id="dq2" data-act="dq2" value="${esc(S.ui.dq2||'')}" placeholder="Search delegates" style="max-width:300px;margin:8px 0"><div class="list">${shown.slice(0,100).map(d=>`<div class="item" style="padding:5px 0"><div class="row between"><div class="small"><b>${esc(d.name)}</b> · ${esc(d.company||'')} · ${esc(d.email||'')} · ${esc((tt.find(t=>t.id===d.ticketTypeId)||{name:'—'}).name)} <span class="pill ${d.status==='checked-in'?'ok':d.status==='cancelled'?'bad':'grey'}">${d.status}</span>${d.consent?'':' <span class="pill warn">no messaging consent</span>'}${d.paidPaise?' · paid '+inr(d.paidPaise):''}</div><div class="row" style="gap:4px">${d.status==='registered'||d.status==='confirmed'?`<button class="btn sm pri" data-act="delegate-checkin" data-id="${d.id}">Check in</button><button class="btn sm" data-act="delegate-cancel" data-id="${d.id}">Cancel</button>`:''}</div></div></div>`).join('')||'<div class="muted small">No delegates.</div>'}</div></div>`}
ACTS_INPUT['dq2']=el=>{S.ui.dq2=el.value;saveUI();const pos=el.selectionStart;render();const n=F('dq2');if(n){n.focus();try{n.setSelectionRange(pos,pos)}catch(e){}}};
act('delegate-add',({E})=>{const e=E();openModal(`${hd('Delegate')}<form id="f-dl"><label for="dln">Name</label><input id="dln" required><div class="two"><div><label for="dle">Email</label><input id="dle" type="email"></div><div><label for="dlc">Company</label><input id="dlc"></div></div><label for="dlt">Ticket class</label><select id="dlt"><option value="">—</option>${S.ticketTypes.filter(t=>t.eventId===e.id).map(t=>`<option value="${t.id}">${esc(t.name)} · ${inr(t.pricePaise)}</option>`).join('')}</select><label class="chk"><input type="checkbox" id="dlk"> Agreed to attendee messages</label>${ft('Add')}</form>`);F('f-dl').addEventListener('submit',x=>{x.preventDefault();registerDelegate(e,{name:F('dln').value.trim(),email:F('dle').value.trim(),company:F('dlc').value.trim(),ticketTypeId:F('dlt').value||null,consent:F('dlk').checked,source:'manual'});closeModal();render()})});
function registerDelegate(e,d){if(S.delegates.some(x=>x.eventId===e.id&&x.email&&x.email.toLowerCase()===(d.email||'').toLowerCase()&&x.status!=='cancelled'))return {dup:true};const tt=S.ticketTypes.find(t=>t.id===d.ticketTypeId);if(tt&&tt.sold>=tt.qty)return {soldOut:true};const rec=stamp(Object.assign({id:uid(),eventId:e.id,status:'registered',paidPaise:0,token:Math.random().toString(36).slice(2,10)},d));S.delegates.push(rec);if(tt){tt.sold=(tt.sold||0)+1}save();return {ok:true,rec}}
act('delegate-checkin',({id})=>{const d=S.delegates.find(x=>x.id===id);d.status='checked-in';d.checkedInAt=nowISO();d.checkedInBy=UI.userId;save();render()});
act('delegate-cancel',({id})=>{const d=S.delegates.find(x=>x.id===id);d.status='cancelled';d.cancelledAt=nowISO();const tt=S.ticketTypes.find(t=>t.id===d.ticketTypeId);if(tt)tt.sold=Math.max(0,(tt.sold||0)-1);save();render()});
function vRegister(){const e=eventByToken('registerToken',S.ui.registerToken||'');const back=`<a href="#events" class="btn sm" style="text-decoration:none;margin-top:10px;display:inline-block">← Back to the app</a>`;if(!e||!modOn('registration'))return `<div class="login"><div class="card" style="max-width:520px;margin:30px auto"><h2>Registration closed</h2>${back}</div></div>`;const tt=S.ticketTypes.filter(t=>t.eventId===e.id);const done=S.ui.regDone;return `<div class="login"><div class="card" style="max-width:560px;margin:30px auto"><div class="eyebrow">${esc(e.client)}</div><h1 style="font-size:22px">${esc(e.name)}</h1><div class="small muted">${fmtDate(e.startDate)} · ${esc(e.venue||'')}</div>${done?`<div class="note" style="margin-top:10px">${esc(done)}</div>`:`<form id="f-reg" style="margin-top:8px"><label for="rgn">Name</label><input id="rgn" required><label for="rge">Work email</label><input id="rge" type="email" required><label for="rgc">Company</label><input id="rgc"><label for="rgt">Ticket</label><select id="rgt">${tt.map(t=>`<option value="${t.id}" ${t.sold>=t.qty?'disabled':''}>${esc(t.name)} · ${t.pricePaise?inr(t.pricePaise):'free'}${t.sold>=t.qty?' (sold out)':''}</option>`).join('')||'<option value="">General</option>'}</select><label class="chk"><input type="checkbox" id="rgk"> You may message me about this event</label><label class="chk"><input type="checkbox" id="rgp" required> I agree to the data notice (<a href="#" data-act="privacy-show">read</a>)</label><div class="ft"><button class="btn pri" type="submit">Register</button></div></form>`}<div class="meta" style="margin-top:10px">${sb('public registration page + payment')}</div>${back}</div></div>`}
document.addEventListener('submit',evt=>{if(evt.target.id!=='f-reg')return;evt.preventDefault();const e=eventByToken('registerToken',S.ui.registerToken);const r=registerDelegate(e,{name:F('rgn').value.trim(),email:F('rge').value.trim(),company:F('rgc').value.trim(),ticketTypeId:F('rgt').value||null,consent:F('rgk').checked,source:'web'});S.ui.regDone=r.dup?'This email is already registered.':r.soldOut?'That ticket class is sold out.':'Registered. A confirmation goes to your email.';if(r.ok){S.notes.push({id:uid(),userId:e.plannerId,text:`New registration: ${r.rec.name} (${r.rec.company||'—'})`,ts:nowISO(),read:false,eventId:e.id});save()}saveUI();render()});
/* ticketing, exhibitors, sponsors */
function ticketRevenue(e){const sales=S.ticketSales.filter(s=>s.eventId===e.id);const sold=sum(sales.filter(s=>s.status==='paid'),s=>s.amountPaise);const refunded=sum(sales.filter(s=>s.status==='refunded'),s=>s.refundPaise||s.amountPaise);const sp=sum(S.sponsors.filter(s=>s.eventId===e.id&&s.status==='paid'),s=>s.amountPaise);const ex=sum(S.exhibitors.filter(s=>s.eventId===e.id&&s.status==='paid'),s=>s.amountPaise);return {sold,refunded,sponsors:sp,exhibitors:ex,net:sold-refunded+sp+ex,pending:sum(sales.filter(s=>s.status==='pending'),s=>s.amountPaise)+sum(S.sponsors.filter(s=>s.eventId===e.id&&s.status!=='paid'),s=>s.amountPaise)}}
function ticketingCard(e){const tt=S.ticketTypes.filter(t=>t.eventId===e.id);const tr=ticketRevenue(e);const sp=S.sponsors.filter(s=>s.eventId===e.id),ex=S.exhibitors.filter(s=>s.eventId===e.id);const sales=S.ticketSales.filter(s=>s.eventId===e.id).slice().reverse();return `<div class="card" style="margin-bottom:12px"><div class="row between"><div><h3>Ticketing, exhibitors & sponsors</h3><div class="small muted">A separate revenue lane with its own entitlements, cancellation and refund accounting. Whose revenue it is (yours or the client's) is set on the event; it never silently joins the contract.</div></div>${can('client')&&!locked(e)?`<div class="row" style="gap:6px"><button class="btn sm" data-act="ticket-type">+ Ticket class</button><button class="btn sm" data-act="sponsor-add" data-v="sponsor">+ Sponsor</button><button class="btn sm" data-act="sponsor-add" data-v="exhibitor">+ Exhibitor</button><button class="btn sm" data-act="ticket-owner">Revenue belongs to: ${e.ticketRevenueOwner==='company'?'us':'client'}</button></div>`:''}</div>${seesMoney()?`<div class="grid g4" style="margin:8px 0">${stat('Tickets sold',inr(tr.sold),`refunded ${inr(tr.refunded)}`)}${stat('Sponsors',inr(tr.sponsors),sp.length+' · '+inr(sum(sp.filter(s=>s.status!=='paid'),s=>s.amountPaise))+' not yet paid')}${stat('Exhibitors',inr(tr.exhibitors),ex.length+' stalls')}${stat('Net lane revenue',inr(tr.net),e.ticketRevenueOwner==='company'?'counted as other income for us':'collected for the client, not ours',true)}</div>`:''}<div class="scroll"><table><thead><tr><th>Ticket class</th><th class="r">Price</th><th class="r">Sold / qty</th><th>Entitlements</th><th></th></tr></thead><tbody>${tt.map(t=>`<tr><td><b>${esc(t.name)}</b></td><td class="r num">${t.pricePaise?inr(t.pricePaise):'free'}</td><td class="r num">${t.sold||0} / ${t.qty}${(t.sold||0)>=t.qty?' <span class="pill bad">sold out</span>':''}</td><td class="small">${esc(t.entitlements||'')}</td><td class="small">${t.refundPolicy?esc(t.refundPolicy):''}</td></tr>`).join('')||'<tr><td colspan="5" class="muted">No ticket classes.</td></tr>'}</tbody></table></div>${sales.length?`<div class="eyebrow" style="margin-top:8px">Sales (${sales.length})</div><div class="list">${sales.slice(0,10).map(s=>`<div class="item small" style="padding:4px 0"><div class="row between"><div>${esc((S.delegates.find(d=>d.id===s.delegateId)||{name:'?'}).name)} · ${esc((tt.find(t=>t.id===s.ticketTypeId)||{}).name||'')} · ${inr(s.amountPaise)} <span class="pill ${s.status==='paid'?'ok':s.status==='refunded'?'grey':'warn'}">${s.status}${s.refundPaise?' '+inr(s.refundPaise):''}</span></div><div class="row" style="gap:4px">${s.status==='pending'&&can('client')?`<button class="btn sm pri" data-act="ticket-paid" data-id="${s.id}">Mark paid</button>`:s.status==='paid'&&can('client')?`<button class="btn sm" data-act="ticket-refund" data-id="${s.id}">Refund</button>`:''}</div></div></div>`).join('')}</div>`:''}${sp.length||ex.length?`<div class="eyebrow" style="margin-top:8px">Sponsors & exhibitors</div><div class="list">${sp.concat(ex).map(s=>`<div class="item small" style="padding:4px 0"><div class="row between"><div><b>${esc(s.name)}</b> · ${esc(s.package||s.stall||'')} · ${inr(s.amountPaise)} <span class="pill ${s.status==='paid'?'ok':'warn'}">${s.status}</span>${s.deliverables?' · '+esc(s.deliverables):''}</div>${s.status!=='paid'&&can('client')?`<button class="btn sm pri" data-act="sponsor-paid" data-id="${s.id}">Mark paid</button>`:''}</div></div>`).join('')}</div>`:''}</div>`}
act('ticket-owner',({E})=>{const e=E();e.ticketRevenueOwner=e.ticketRevenueOwner==='company'?'client':'company';touch(e);audit('update','events',e.id,'ticket revenue owner '+e.ticketRevenueOwner,e.id);save();render()});
act('ticket-type',({E})=>{const e=E();openModal(`${hd('Ticket class')}<form id="f-tt"><label for="ttn">Name</label><input id="ttn" required placeholder="Delegate"><div class="two"><div><label for="ttp">Price (₹, 0 = free)</label><input id="ttp" inputmode="decimal" value="0"></div><div><label for="ttq">Quantity</label><input id="ttq" inputmode="numeric" value="100"></div></div><label for="tte">Entitlements</label><input id="tte" placeholder="All sessions, lunch, kit"><label for="ttr">Refund policy</label><input id="ttr" placeholder="Full refund to 7 days before; none after">${ft('Add')}</form>`);F('f-tt').addEventListener('submit',x=>{x.preventDefault();S.ticketTypes.push(stamp({id:uid(),eventId:e.id,name:F('ttn').value.trim(),pricePaise:toPaise(F('ttp').value)||0,qty:parseInt(F('ttq').value)||0,sold:0,entitlements:F('tte').value.trim(),refundPolicy:F('ttr').value.trim()}));save();closeModal();render()})});
act('sponsor-add',({E,v})=>{const e=E();openModal(`${hd(v==='sponsor'?'Sponsor':'Exhibitor')}<form id="f-sp"><label for="spn">Name</label><input id="spn" required><div class="two"><div><label for="spp">${v==='sponsor'?'Package':'Stall'}</label><input id="spp"></div><div><label for="spa">Amount (₹, ex-tax)</label><input id="spa" inputmode="decimal" required></div></div><label for="spd">Deliverables owed to them</label><input id="spd" placeholder="Logo on backdrop, 2 passes, 5-min slot">${ft('Add')}</form>`);F('f-sp').addEventListener('submit',x=>{x.preventDefault();const rec=stamp({id:uid(),eventId:e.id,name:F('spn').value.trim(),[v==='sponsor'?'package':'stall']:F('spp').value.trim(),amountPaise:toPaise(F('spa').value)||0,deliverables:F('spd').value.trim(),status:'agreed'});(v==='sponsor'?S.sponsors:S.exhibitors).push(rec);save();closeModal();render()})});
function laneIncome(e,rec,kind,amt){if(e.ticketRevenueOwner==='company'){S.otherIncome.push(stamp({id:uid(),eventId:e.id,vendorId:null,desc:kind+': '+rec.name,amountPaise:amt,date:todayStr(),laneRef:rec.id}))}}
act('sponsor-paid',({E,id})=>{const e=E();const s=S.sponsors.find(x=>x.id===id)||S.exhibitors.find(x=>x.id===id);s.status='paid';s.paidAt=nowISO();laneIncome(e,s,s.package?'Sponsor':'Exhibitor',s.amountPaise);save();render()});
act('ticket-paid',({E,id})=>{const e=E();const s=S.ticketSales.find(x=>x.id===id);s.status='paid';s.paidAt=nowISO();const d=S.delegates.find(x=>x.id===s.delegateId);if(d){d.paidPaise=s.amountPaise;d.status='confirmed'}laneIncome(e,{id:s.id,name:(d||{}).name||'ticket'},'Ticket',s.amountPaise);save();render()});
act('ticket-refund',({E,id})=>{const e=E();const s=S.ticketSales.find(x=>x.id===id);openModal(`${hd('Refund ticket')}<form id="f-tr2"><p class="small">${esc((S.ticketTypes.find(t=>t.id===s.ticketTypeId)||{}).refundPolicy||'No refund policy recorded on the ticket class.')}</p><label for="tra">Refund amount (₹)</label><input id="tra" class="big" inputmode="decimal" value="${s.amountPaise/100}">${ft('Refund')}</form>`);F('f-tr2').addEventListener('submit',x=>{x.preventDefault();const a=toPaise(F('tra').value)||0;if(a>s.amountPaise)return toast('More than paid');s.status='refunded';s.refundPaise=a;s.refundedAt=nowISO();const d=S.delegates.find(z=>z.id===s.delegateId);if(d){d.status='cancelled';const tt=S.ticketTypes.find(t=>t.id===d.ticketTypeId);if(tt)tt.sold=Math.max(0,(tt.sold||0)-1)}if(e.ticketRevenueOwner==='company')S.otherIncome.push(stamp({id:uid(),eventId:e.id,vendorId:null,desc:'Ticket refund: '+((d||{}).name||''),amountPaise:-a,date:todayStr(),laneRef:s.id}));save();closeModal();render()})});
/* speakers & sessions */
function sessionConflicts(e){const ss=S.confSessions.filter(s=>s.eventId===e.id);const out=[];for(let i=0;i<ss.length;i++)for(let j=i+1;j<ss.length;j++){const a=ss[i],b=ss[j];if(a.fn!==b.fn||a.start>=b.end||b.start>=a.end)continue;if(a.room&&a.room===b.room)out.push(`${a.title} and ${b.title} overlap in ${a.room}`);const shared=(a.speakerIds||[]).filter(x=>(b.speakerIds||[]).includes(x));shared.forEach(id=>out.push(`${(S.speakers.find(s=>s.id===id)||{}).name} is in two sessions at once (${a.title}, ${b.title})`))}return out}
function sessionsCard(e){const ss=S.confSessions.filter(s=>s.eventId===e.id).sort((a,b)=>(a.fn+a.start).localeCompare(b.fn+b.start));const sp=S.speakers.filter(s=>s.eventId===e.id);const cf=sessionConflicts(e);return `<div class="card"><div class="row between"><div><h3>Speakers & sessions</h3><div class="small muted">Submissions, assets, confirmation and travel per speaker; sessions with room and time; conflicts flagged; stage cues become run-sheet lines.</div></div>${can('events.edit')&&!locked(e)?`<div class="row" style="gap:6px"><button class="btn sm" data-act="speaker-add">+ Speaker</button><button class="btn sm" data-act="session-add">+ Session</button><button class="btn sm pri" data-act="cues-make">Generate stage cues</button></div>`:''}</div>${cf.length?`<div class="alert" style="margin-top:6px">${cf.map(esc).join('<br>')}</div>`:''}<div class="list" style="margin-top:6px">${ss.map(s=>`<div class="item small" style="padding:5px 0"><b>${s.start}–${s.end}</b> ${esc(s.title)} · ${esc(s.room||'')} · ${(s.speakerIds||[]).map(id=>esc((sp.find(x=>x.id===id)||{name:'?'}).name)).join(', ')} <span class="pill ${s.status==='confirmed'?'ok':'warn'}">${s.status}</span>${s.cueId?' · cue in run sheet':''}</div>`).join('')||'<div class="muted small">No sessions.</div>'}</div><div class="eyebrow" style="margin-top:8px">Speakers (${sp.length})</div><div class="list">${sp.map(s=>`<div class="item small" style="padding:4px 0"><b>${esc(s.name)}</b> · ${esc(s.topic||'')} <span class="pill ${s.confirmed?'ok':'warn'}">${s.confirmed?'confirmed':'not confirmed'}</span>${s.assets?' · assets: '+esc(s.assets):' · <span class="pill warn">no slides/bio</span>'}${s.travel?' · travel: '+esc(s.travel):''}</div>`).join('')||'<div class="muted small">None.</div>'}</div></div>`}
act('speaker-add',({E})=>{const e=E();openModal(`${hd('Speaker')}<form id="f-spk"><label for="skn">Name</label><input id="skn" required><label for="skt">Topic</label><input id="skt"><label for="ska">Assets received (slides, bio, photo)</label><input id="ska"><label for="skv">Travel</label><input id="skv" placeholder="Flight from Bangalore, hotel 1 night"><label class="chk"><input type="checkbox" id="skc"> Confirmed</label>${ft('Add')}</form>`);F('f-spk').addEventListener('submit',x=>{x.preventDefault();S.speakers.push(stamp({id:uid(),eventId:e.id,name:F('skn').value.trim(),topic:F('skt').value.trim(),assets:F('ska').value.trim(),travel:F('skv').value.trim(),confirmed:F('skc').checked}));save();closeModal();render()})});
act('session-add',({E})=>{const e=E();openModal(`${hd('Session')}<form id="f-ss"><label for="sst">Title</label><input id="sst" required><div class="grid g3" style="gap:8px"><div><label for="ssf">Function</label><select id="ssf">${fnNames(e).map(f=>`<option>${esc(f)}</option>`).join('')}</select></div><div><label for="sss">Start</label><input id="sss" type="time" value="10:00"></div><div><label for="sse">End</label><input id="sse" type="time" value="10:45"></div></div><div class="two"><div><label for="ssr">Room / stage</label><input id="ssr" value="Main stage"></div><div><label for="ssk">Speakers</label><select id="ssk" multiple>${S.speakers.filter(s=>s.eventId===e.id).map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></div></div>${ft('Add')}</form>`);F('f-ss').addEventListener('submit',x=>{x.preventDefault();S.confSessions.push(stamp({id:uid(),eventId:e.id,title:F('sst').value.trim(),fn:F('ssf').value,start:F('sss').value,end:F('sse').value,room:F('ssr').value.trim(),speakerIds:[...F('ssk').selectedOptions].map(o=>o.value),status:'planned',cueId:null}));save();closeModal();render()})});
act('cues-make',({E})=>{const e=E();let n=0;S.confSessions.filter(s=>s.eventId===e.id&&!s.cueId).forEach(s=>{const r=stamp({id:uid(),eventId:e.id,functionName:s.fn,time:s.start,title:`Stage: ${s.title}${s.speakerIds.length?' — '+s.speakerIds.map(id=>(S.speakers.find(x=>x.id===id)||{}).name).join(', '):''}`,ownerId:e.plannerId,commitmentId:null,notes:s.room,done:false});S.runsheet.push(r);s.cueId=r.id;n++});if(n){e.runsheetRev=(e.runsheetRev||0)+1;e.runsheetLog=(e.runsheetLog||[]).concat([{rev:e.runsheetRev,ts:nowISO(),by:UI.userId,what:n+' stage cues generated from sessions',material:false}])}save();render();toast(n+' cue(s) added to the run sheet')});
/* travel & insurance records */
addTab('travel','Travel & insurance',tabTravel,(e,pre)=>!pre&&modOn('travel')&&can('vendors'),'Work');
function tabTravel(e,c){const bs=S.travelBookings.filter(b=>b.eventId===e.id);return `<div class="card"><div class="row between"><div><h2>Travel & insurance records</h2><div class="small muted">Bookings made through qualified providers, with fee, who pays and cancellation terms disclosed. The company records them; it does not sell travel or insurance and takes no undisclosed commission. ${sb('travel/insurance provider')}</div></div>${can('vendors')&&!locked(e)?`<button class="btn sm pri" data-act="travel-add">+ Booking</button>`:''}</div><div class="list" style="margin-top:6px">${bs.map(b=>`<div class="item" style="padding:6px 0"><div class="small"><b>${esc(b.kind)}</b> · ${esc(b.for)} · ${esc(b.provider)} ${b.ref?'· '+esc(b.ref):''} · ${inr(b.amountPaise)}${b.feePaise?' (incl. provider fee '+inr(b.feePaise)+')':''} · paid by ${b.payer} <span class="pill ${b.status==='confirmed'?'ok':b.status==='cancelled'?'bad':'warn'}">${b.status}</span><div class="meta">Cancellation: ${esc(b.cancelTerms||'unknown')}${b.payer==='company'?' · recorded as an expense':''}</div></div></div>`).join('')||'<div class="muted small">None.</div>'}</div></div>`}
act('travel-add',({E})=>{const e=E();openModal(`${hd('Travel / insurance booking')}<form id="f-tv"><div class="two"><div><label for="tvk">Kind</label><select id="tvk"><option>flight</option><option>train</option><option>hotel</option><option>event insurance</option><option>travel insurance</option></select></div><div><label for="tvf">For whom</label><input id="tvf" required placeholder="Speaker: Anil Kumar / 5 guests"></div></div><div class="two"><div><label for="tvp">Provider</label><input id="tvp" placeholder="MakeMyTrip / ICICI Lombard"></div><div><label for="tvr">Reference</label><input id="tvr"></div></div><div class="grid g3" style="gap:8px"><div><label for="tva">Amount (₹)</label><input id="tva" inputmode="decimal" required></div><div><label for="tvfe">Of which provider fee (₹)</label><input id="tvfe" inputmode="decimal" value="0"></div><div><label for="tvw">Paid by</label><select id="tvw"><option value="client">client directly</option><option value="company">company (expense)</option><option value="guest">the traveller</option></select></div></div><label for="tvc">Cancellation terms</label><input id="tvc" placeholder="Non-refundable / free to 48h">${ft('Record')}</form>`);F('f-tv').addEventListener('submit',x=>{x.preventDefault();const amt=toPaise(F('tva').value)||0;const b=stamp({id:uid(),eventId:e.id,kind:F('tvk').value,for:F('tvf').value.trim(),provider:F('tvp').value.trim(),ref:F('tvr').value.trim(),amountPaise:amt,feePaise:toPaise(F('tvfe').value)||0,payer:F('tvw').value,cancelTerms:F('tvc').value.trim(),status:'confirmed'});S.travelBookings.push(b);if(b.payer==='company')S.expenses.push(stamp({id:uid(),eventId:e.id,functionName:'',amountPaise:amt,category:'Transport',source:'company',date:todayStr(),note:b.kind+' for '+b.for+' via '+b.provider,photo:'',spentBy:UI.userId,settlementId:null,status:'approved',travelId:b.id}));save();closeModal();render()})});
/* ---------- Assistants (review-first, never auto-commit) ---------- */
addPage('assistant','Assistants',vAssistant,()=>modOn('ai')&&can('quote'));
function draftQuote(e){const tpl=(S.company.quoteTemplates||[]).find(t=>t.type===e.type);const lines=[];const missing=[];const assumptions=[];(tpl?tpl.lines:[]).forEach(l=>{const [cat,desc,perGuest,cost,price]=l;const pb=priceBookFor(cat,e);let uc=cost*100,up=price*100,src='template';if(pb&&/median ₹/.test(pb.text)){const m=pb.text.match(/median (₹[\d,]+)/);if(m){const med=toPaise(m[1]);if(med){uc=med;up=Math.round(med*(price/cost||1.2));src='price book median'}}}if(!cost&&!pb)missing.push(cat+': no template cost and no price book entry — unknown');lines.push({category:cat,desc,qty:perGuest?(e.guests||0):1,unitCostPaise:uc,unitPricePaise:up,perGuest:!!perGuest,src})});if(!tpl)missing.push('No quote template for type "'+e.type+'"');assumptions.push('Quantities for per-guest lines use the event headcount ('+(e.guests||0)+')');assumptions.push('Prices keep each template line\'s margin ratio; price-book medians replace template costs where they exist');return {lines,missing,assumptions}}
function draftTimeline(e,fn){const d=fnOf(e,fn);const lines=[];const toMin=t=>{const [h,m]=t.split(':').map(Number);return h*60+m};const fmt=m=>String(Math.floor(((m%1440)+1440)%1440/60)).padStart(2,'0')+':'+String(m%60).padStart(2,'0');const start=d.start?toMin(d.start):600;agreedComms(e.id).filter(cm=>!(cm.functions||[]).length||cm.functions.includes(fn)).forEach(cm=>{const v=vendor(cm.vendorId);const lead=({Décor:300,Catering:150,Photography:90,Makeup:240,Music:120,Venue:0,Transport:60,Priest:60}[v.category]||90)+(cm.travelMin||0);if(v.category!=='Venue')lines.push({time:fmt(start-lead),title:`${v.name} arrives / sets up (${v.category})`,cmId:cm.id,why:`${lead-(cm.travelMin||0)} min before start for ${v.category}${cm.travelMin?' + '+cm.travelMin+' min travel':''}${cm.setupWindow?' · vendor window: '+cm.setupWindow:''}`})});lines.push({time:fmt(start),title:`${fn} begins`,cmId:null,why:'function start time'});return lines.sort((a,b)=>a.time.localeCompare(b.time))}
function changeSummary(e,a,b,audience){let d=snapDiff(a,b).replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim();if(audience!=='internal')d=d.replace(/;?\s*cost ₹[\d,]+ → ₹[\d,]+/g,'');const base=`Quote v${a.n} → v${b.n} for ${e.name}: price ${inr(a.totals.net)} → ${inr(b.totals.net)}`;if(audience==='client')return `${base}.\nWhat changed: ${d.split('Price')[0].trim()}\nTotal payable now ${inr(b.totals.gross)}${b.tax.on?' incl. GST':''}.`;if(audience==='staff')return `${base.replace(/price [^:]*$/,'')}. Scope changes: ${d.split('Price')[0].trim()} — no prices for your role.`;return `${base}; cost ${inr(a.totals.cost)} → ${inr(b.totals.cost)}; margin ${inr(a.totals.margin)} → ${inr(b.totals.margin)}.\n${d}`}
function vAssistant(){const eid=S.ui.aiEvent||(S.events.find(e=>!e.history&&e.stage!=='closed')||{}).id;const e=ev(eid);if(!e)return `${topbar()}<h1>Assistants</h1><div class="muted">No events.</div>`;const dq=draftQuote(e);const fn=fnNames(e)[0];const tl=draftTimeline(e,fn);const snaps=e.quote.snapshots||[];const cs=snaps.length>=2?changeSummary(e,snaps[snaps.length-2],snaps[snaps.length-1],S.ui.aiAud||'internal'):null;const sugg=live(S.expenses).filter(x=>x.suggested&&!x.suggested.accepted);
  return `${topbar()}<div class="row between"><h1>Assistants</h1><select data-act="ai-event" style="width:auto;font-size:13px;padding:6px 10px">${S.events.filter(x=>!x.history).map(x=>`<option value="${x.id}" ${x.id===e.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="small muted" style="margin:4px 0 10px">Rule-based drafts from your own data — templates, price book, vendor windows, snapshots. Every draft shows its assumptions and missing inputs, and nothing becomes a price, order, payment or promise until a person accepts it. No model is called in this build; the spec defines where one would plug in with the same review step.</div>
  <div class="card" style="margin-bottom:12px"><div class="row between"><h3>Draft quote for ${esc(e.name)}</h3>${stageIdx(e.stage)<2&&can('quote')?`<button class="btn sm pri" data-act="ai-apply-quote">Use as the quote draft</button>`:'<span class="pill grey">event already quoted/confirmed</span>'}</div><div class="scroll" style="margin-top:6px"><table><thead><tr><th>Line</th><th class="r">Qty</th><th class="r">Unit cost</th><th class="r">Unit price</th><th>Source</th></tr></thead><tbody>${dq.lines.map(l=>`<tr><td>${esc(l.category)} · ${esc(l.desc)}</td><td class="r num">${l.qty}</td><td class="r num">${inr(l.unitCostPaise)}</td><td class="r num">${inr(l.unitPricePaise)}</td><td class="small">${esc(l.src)}</td></tr>`).join('')||'<tr><td colspan="5" class="muted">Nothing to draft.</td></tr>'}</tbody></table></div>${dq.missing.length?`<div class="alert" style="margin-top:6px">${dq.missing.map(esc).join('<br>')}</div>`:''}<div class="meta">Assumptions: ${dq.assumptions.map(esc).join(' · ')}</div></div>
  <div class="card" style="margin-bottom:12px"><div class="row between"><h3>Draft timeline · ${esc(fn)}</h3>${can('runsheet')&&!locked(e)?`<button class="btn sm pri" data-act="ai-apply-timeline" data-v="${esc(fn)}">Add these lines (planner confirms)</button>`:''}</div><div class="list" style="margin-top:4px">${tl.map(l=>`<div class="item small" style="padding:4px 0"><b>${l.time}</b> ${esc(l.title)}<div class="meta">${esc(l.why)}</div></div>`).join('')}</div></div>
  ${cs?`<div class="card" style="margin-bottom:12px"><div class="row between"><h3>Change summary (latest two quote versions)</h3><div class="chips">${['internal','client','staff'].map(a=>`<button class="btn chip sm ${(S.ui.aiAud||'internal')===a?'on':''}" data-act="ai-aud" data-v="${a}">${a}</button>`).join('')}</div></div><pre class="small" style="white-space:pre-wrap;margin-top:6px">${esc(cs)}</pre><div class="meta">Client and staff versions carry no internal margin.</div></div>`:''}
  <div class="card" style="margin-bottom:12px"><h3>Receipt extraction review (${sugg.length})</h3><div class="list">${sugg.map(x=>`<div class="item small" style="padding:4px 0"><div class="row between"><div>${esc(user(x.spentBy).name)} · entered ${inr(x.amountPaise)} on ${fmtShort(x.date)} · suggested ${x.suggested.amountPaise?inr(x.suggested.amountPaise):'nothing'} (${x.suggested.confidence})<div class="meta">${esc(x.suggested.source)}</div></div><div class="row" style="gap:4px"><button class="btn sm" data-act="ai-accept-ocr" data-id="${x.id}">Accept suggestion</button><button class="btn sm" data-act="ai-reject-ocr" data-id="${x.id}">Keep entered</button></div></div></div>`).join('')||'<div class="muted small">Nothing to review.</div>'}</div></div>
  <div class="card"><h3>Risk explanations</h3><div class="small muted">Every alert on Exceptions and Home comes from a rule you can read, with the record it points at. There is no "event health score". ${exceptions().slice(0,3).map(x=>`<div class="small" style="margin-top:4px"><b>${esc(x.kind)}</b> on ${esc(x.e.name)}: ${esc(x.txt)} — rule: ${esc(({'Thin margin':'forecast margin below the company thin-margin %','Unpriced scope':'change raised with cost but no client price','Client decision overdue':'approval link unanswered 5+ days','Vendor not confirmed':'no accepted work order within 30 days of the event','Collection overdue':'milestone past due with balance','Scope nothing booked':'open scope line with no agreement within 45 days','Funding need':'vendor outstanding exceeds cash in hand from this event'})[x.kind]||'')}</div>`).join('')}</div></div>`}
ACTS_CHANGE['ai-event']=el=>{S.ui.aiEvent=el.value;saveUI();render()};act('ai-aud',({v})=>{S.ui.aiAud=v;saveUI();render()});
act('ai-apply-quote',()=>{const e=ev(S.ui.aiEvent||(S.events.find(x=>!x.history&&x.stage!=='closed')||{}).id);const dq=draftQuote(e);if(!dq.lines.length)return toast('Nothing to apply');mConfirm('Use the draft','Replaces the current quote lines with the draft. You still edit, send and the client accepts — nothing is sent now.','Use draft',()=>{e.quote.lines=dq.lines.map(l=>({id:uid(),category:l.category,desc:l.desc,qty:l.qty,unitCostPaise:l.unitCostPaise,unitPricePaise:l.unitPricePaise,perGuest:l.perGuest}));touch(e);audit('update','events',e.id,'quote drafted by assistant (reviewed)',e.id);save();closeModal();go('event',e.id)})});
act('ai-apply-timeline',({v})=>{const e=ev(S.ui.aiEvent||(S.events.find(x=>!x.history&&x.stage!=='closed')||{}).id);const tl=draftTimeline(e,v);mConfirm('Add draft lines','Adds '+tl.length+' run-sheet lines owned by the planner; edit or delete any of them afterwards.','Add',()=>{tl.forEach(l=>S.runsheet.push(stamp({id:uid(),eventId:e.id,functionName:v,time:l.time,title:l.title,ownerId:e.plannerId,commitmentId:l.cmId,notes:'draft: '+l.why,done:false})));e.runsheetRev=(e.runsheetRev||0)+1;e.runsheetLog=(e.runsheetLog||[]).concat([{rev:e.runsheetRev,ts:nowISO(),by:UI.userId,what:tl.length+' draft lines added by assistant (confirmed by '+me().name+')',material:false}]);save();closeModal();S.ui.tab='runsheet';go('event',e.id)})});
act('ai-accept-ocr',({id})=>{const x=S.expenses.find(z=>z.id===id);if(x.suggested.amountPaise){x.history=(x.history||[]).concat(['Amount '+inr(x.amountPaise)+' → '+inr(x.suggested.amountPaise)+' per OCR suggestion, accepted by '+me().name]);x.amountPaise=x.suggested.amountPaise}x.suggested.accepted=true;touch(x);save();render()});act('ai-reject-ocr',({id})=>{const x=S.expenses.find(z=>z.id===id);x.suggested.accepted=true;x.suggested.rejected=true;save();render()});
/* ---------- Benchmark opt-in, sourcing network, multi-currency ---------- */
addPage('benchmark','Benchmarks',vBenchmark,()=>modOn('benchmark')&&can('profit'));
function vBenchmark(){const b=S.company.benchmark||{optIn:false,shareFields:['category','unit','rate','city','month'],at:null};return `${topbar()}<h1>Benchmarks</h1><div class="card" style="margin-bottom:12px"><h3>Private estimating intelligence</h3><div class="small muted">Your own reviewed scope lines and actuals, by category, unit, city and date, with sample size and confidence — this is the Price book and the Profitability by segment pages. Naive all-event per-guest averages are deliberately not used.</div><div class="row" style="gap:6px;margin-top:6px"><a class="btn sm" href="#pricebook" style="text-decoration:none">Price book</a><a class="btn sm" href="#segments" style="text-decoration:none">Segments</a></div></div><div class="card"><h3>Cross-company benchmark <span class="pill grey">not available</span></h3><div class="small muted">Would compare your rates with other participating companies in the same city and category — only with explicit data rights, aggregation over at least 5 companies and 20 data points per cell, and never your client or vendor names. Participating companies today: <b>unknown (1 — you)</b>. It is not a launch assumption and not a "moat".</div><label class="chk" style="margin-top:8px"><input type="checkbox" id="bmo" data-act="bm-optin" ${b.optIn?'checked':''}> Opt in to share anonymised rates (${b.shareFields.join(', ')}) when the pool exists${b.at?' · opted in '+fmtTs(b.at):''}</label></div>`}
ACTS_CHANGE['bm-optin']=el=>{S.company.benchmark=Object.assign(S.company.benchmark||{shareFields:['category','unit','rate','city','month']},{optIn:el.checked,at:el.checked?nowISO():null,by:UI.userId});audit('update','benchmark','company',el.checked?'opt in':'opt out',null);save();render()};
addPage('sourcing','Sourcing network',vSourcing,()=>modOn('marketplace')&&can('vendors'));
function vSourcing(){const m=S.company.marketplace||{listed:[],interest:false};return `${topbar()}<h1>Sourcing network <span class="pill grey">deferred</span></h1><div class="card"><div class="small">A shared vendor directory across planning companies needs verified supply, dispute and payment operations, and real demand — none of which exist yet. Rather than bolt on a listing, this page records interest and which of your vendors you would be willing to recommend. Nothing is published anywhere.</div><label class="chk" style="margin-top:8px"><input type="checkbox" data-act="mk-interest" ${m.interest?'checked':''}> We would use a shared, verified vendor network if one existed</label><div class="eyebrow" style="margin-top:8px">Vendors we would recommend (private list)</div><div class="chips" style="margin-top:4px">${S.vendors.filter(v=>v.id!=='v_other').map(v=>`<button class="btn chip sm ${m.listed.includes(v.id)?'on':''}" data-act="mk-list" data-id="${v.id}">${esc(v.name)}</button>`).join('')}</div></div>`}
ACTS_CHANGE['mk-interest']=el=>{S.company.marketplace=Object.assign(S.company.marketplace||{listed:[]},{interest:el.checked});save();render()};act('mk-list',({id})=>{const m=S.company.marketplace=S.company.marketplace||{listed:[],interest:false};const i=m.listed.indexOf(id);if(i>=0)m.listed.splice(i,1);else m.listed.push(id);save();render()});
/* multi-currency: receipts in foreign currency with rate, settlement rate, gain/loss */
addPage('fx','Multi-currency',vFx,()=>modOn('fx')&&can('profit'));
function fxSummary(){const rs=live(S.receipts).filter(r=>r.currency&&r.currency!=='INR');return rs.map(r=>{const booked=r.amountPaise;const settled=r.settledPaise!=null?r.settledPaise:null;const fee=r.fxFeePaise||0;return {r,booked,settled,gain:settled!=null?settled-booked-fee:null,fee}})}
function vFx(){const rows=fxSummary();const rates=S.fxRates.slice().reverse();return `${topbar()}<div class="row between"><h1>Multi-currency</h1><div class="row" style="gap:6px"><button class="btn sm" data-act="fx-rate">+ Rate</button></div></div><div class="small muted" style="margin:4px 0 10px">Foreign-currency receipts are booked in INR at the rate on the day; when the bank credits the money, the settled INR and fees are recorded and the difference is a realised gain or loss (ex-tax). Currency-specific ledgers and unrealised revaluation are not built: cross-border demand is <b>unknown</b>. Fields exist so the data is right when it is needed. ${sb('rate source')}</div><div class="card" style="margin-bottom:12px"><h3>Foreign-currency receipts</h3><div class="scroll"><table><thead><tr><th>Event</th><th class="r">Amount</th><th class="r">Rate</th><th class="r">Booked INR</th><th class="r">Settled INR</th><th class="r">Fees</th><th class="r">Gain / loss</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc((ev(x.r.eventId)||{}).name)} · ${fmtShort(x.r.date)}</td><td class="r num">${x.r.currency} ${(x.r.fxAmount||0).toFixed(2)}</td><td class="r num">${x.r.fxRate||'—'}</td><td class="r num">${inr(x.booked)}</td><td class="r num">${x.settled!=null?inr(x.settled):'—'}</td><td class="r num">${inr(x.fee)}</td><td class="r num" style="color:${x.gain==null?'inherit':x.gain<0?'var(--bad)':'var(--ok)'}">${x.gain==null?'—':(x.gain<0?'−':'+')+inr(Math.abs(x.gain))}</td><td>${x.settled==null?`<button class="btn sm" data-act="fx-settle" data-id="${x.r.id}">Record settlement</button>`:''}</td></tr>`).join('')||'<tr><td colspan="8" class="muted">No foreign-currency receipts. Record one from Client money with a currency.</td></tr>'}</tbody></table></div><div class="meta">Realised total: ${inr(sum(rows.filter(x=>x.gain!=null),x=>x.gain))}</div></div><div class="card"><h3>Rates used</h3><div class="list">${rates.map(r=>`<div class="item small" style="padding:4px 0">${r.date} · 1 ${r.currency} = ₹${r.rate} · ${esc(r.source)}</div>`).join('')||'<div class="muted small">None recorded.</div>'}</div></div>`}
act('fx-rate',()=>{openModal(`${hd('Exchange rate')}<form id="f-fx"><div class="grid g3" style="gap:8px"><div><label for="fxc">Currency</label><input id="fxc" value="USD"></div><div><label for="fxr">₹ per unit</label><input id="fxr" inputmode="decimal"></div><div><label for="fxd">Date</label><input id="fxd" type="date" value="${todayStr()}"></div></div><label for="fxs">Source</label><input id="fxs" placeholder="Bank rate card / RBI reference">${ft('Save')}</form>`);F('f-fx').addEventListener('submit',x=>{x.preventDefault();S.fxRates.push({id:uid(),currency:F('fxc').value.trim().toUpperCase(),rate:parseFloat(F('fxr').value)||0,date:F('fxd').value,source:F('fxs').value.trim()});save();closeModal();render()})});
act('fx-settle',({id})=>{const r=S.receipts.find(x=>x.id===id);openModal(`${hd('Bank settlement')}<form id="f-fs"><p class="small">Booked ${inr(r.amountPaise)} for ${r.currency} ${(r.fxAmount||0).toFixed(2)} at ${r.fxRate}.</p><div class="two"><div><label for="fss">INR credited by the bank</label><input id="fss" class="big" inputmode="decimal" required></div><div><label for="fsf">Bank / FX fees (₹)</label><input id="fsf" inputmode="decimal" value="0"></div></div>${ft('Record')}</form>`);F('f-fs').addEventListener('submit',x=>{x.preventDefault();r.settledPaise=toPaise(F('fss').value);r.fxFeePaise=toPaise(F('fsf').value)||0;r.settledAt=nowISO();const gain=r.settledPaise-r.amountPaise-r.fxFeePaise;if(gain)S.otherIncome.push(stamp({id:uid(),eventId:r.eventId,vendorId:null,desc:'FX '+(gain<0?'loss':'gain')+' on '+r.currency+' receipt',amountPaise:gain,date:todayStr(),fxReceiptId:r.id}));touch(r);save();closeModal();render()})});
const _mReceiptBase=mReceipt;mReceipt=function(m){_mReceiptBase(m);if(!modOn('fx'))return;const f=document.querySelector('.modal form');if(!f)return;f.querySelector('.ft').insertAdjacentHTML('beforebegin',`<details><summary>Foreign currency?</summary><div class="grid g3" style="gap:8px"><div><label for="rcc">Currency</label><input id="rcc" placeholder="USD"></div><div><label for="rca">Amount in that currency</label><input id="rca" inputmode="decimal"></div><div><label for="rcr">Rate (₹ per unit)</label><input id="rcr" inputmode="decimal"></div></div><div class="help">The INR amount above is what is booked; settlement and gain/loss are recorded under Multi-currency when the bank credits.</div></details>`);onSubmitBefore(f,()=>{const c=F('rcc').value.trim().toUpperCase(),a=parseFloat(F('rca').value),r=parseFloat(F('rcr').value);setTimeout(()=>{if(!modalClosed()||!c)return;const rec=S.receipts[S.receipts.length-1];if(rec&&rec.milestoneId===m.id&&!rec.currency){rec.currency=c;rec.fxAmount=a||null;rec.fxRate=r||null;if(r&&!S.fxRates.some(x=>x.currency===c&&x.date===rec.date))S.fxRates.push({id:uid(),currency:c,rate:r,date:rec.date,source:'entered with receipt'});save()}},0)})};
